# Check if mirrored values are ORIGINAL or REVERSED
bg = 6

def check_mirroring(row):
    width = len(row)
    min_col = None
    max_col = None

    for i in range(width):
        if row[i] != bg:
            if min_col is None or i < min_col:
                min_col = i
            if max_col is None or i > max_col:
                max_col = i

    if min_col is None:
        return "No pattern"

    # Check left-side-to-right-side mirroring
    results = []
    for c in range(min_col, max_col + 1):
        mirror_c = width - 1 - c

        # Make sure this column is beyond the original pattern
        if mirror_c > max_col:
            orig_val = row[c]
            mirror_val = row[mirror_c]

            results.append({
                'src_col': c,
                'dst_col': mirror_c,
                'orig_val': orig_val,
                'mirror_val': mirror_val,
                'match': orig_val == mirror_val
            })

    return results

print("Checking mirroring:")
for r in [2, 5, 6, 7, 23]:
    print(f"\nRow {r} input: {input_d[r]}")
    res = check_mirroring(input_d[r])
    for item in res:
        status = "✓ MATCH" if item['match'] else "✗ NO MATCH"
        print(f"  Col {item['src_col']}→{item['dst_col']}: {item['orig_val']}↔{item['mirror_val']}{status}")

